#include <vector>
#include <cstddef>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double even_product = 1.0;
    double odd_product  = 1.0;

    // Compute products of even and odd indices separately with reductions.
    #pragma omp parallel for reduction(*:even_product, odd_product) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(x.size()); ++i) {
        if ((i & 1) == 0) {
            even_product *= x[static_cast<std::size_t>(i)];
        } else {
            odd_product *= x[static_cast<std::size_t>(i)];
        }
    }

    return even_product / odd_product;
}
